#!/usr/bin/env python3
from pathlib import Path
import base64, gzip, sys

if len(sys.argv) != 2:
    raise SystemExit("usage: 0145-dense-boundary-fog.py <source-root>")
root = Path(sys.argv[1]).resolve()

# Version
p = root / "gradle.properties"
s = p.read_text()
if "mod_version=0.1.44-dev" not in s:
    raise SystemExit("Expected 0.1.44-dev version marker not found")
p.write_text(s.replace("mod_version=0.1.44-dev", "mod_version=0.1.45-dev", 1))

FILES = {'src/main/java/dev/futurae/veilbound/client/render/VeilBoundaryRenderer.java': '', 'src/main/resources/assets/veilbound/shaders/core/veil_boundary.fsh': 'H4sIAHv7nGoC/1MuSy0qzszPUzA2NuDiyi8tUShLTTZRSCtKTHfOz8kvsubiKsvPTFHITczM09BUqOZSAAK4rIItWLmGgZ6BjgKCMNQz0LTmquUCANvmbHxdAAAA', 'src/main/resources/assets/veilbound/shaders/core/veil_boundary_fog.fsh': ''}
for rel, encoded in FILES.items():
    p = root / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(gzip.decompress(base64.b64decode(encoded)))

# Documentation
p = root / "README.md"
s = p.read_text()
marker = "## 0.1.45-dev — Dense boundary fog and camera clearance\n"
if marker not in s:
    s += """\n\n## 0.1.45-dev — Dense boundary fog and camera clearance\n\n- The physical Veil membrane is completely opaque pure black with no animated color contribution.\n- Uniform neutral-charcoal fog is emitted inward from all six boundary faces with exactly the same baseline strength.\n- Fog remains a dense bank through the first block and continues as rolling wisps through blocks two and three.\n- Thirty-two spatial slices provide real parallax/depth instead of a flat surface overlay.\n- A one-block spherical exclusion volume is carved around the active camera so fog never renders directly in the player's face when approaching a boundary.\n- The 0.10-block tangential face overlap remains in place to keep corners watertight without changing collision bounds.\n"""
    p.write_text(s)

print("Applied 0.1.45 dense boundary fog and one-block camera clearance")
